class Solution {
public:
    string removeDuplicateLetters(string s) {
        vector<int> last_idx(26, 0);
        for (int i = 0; i < (int)s.size(); i++) last_idx[s[i] - 'a'] = i;
        vector<bool> seen(26, false);
        string st;
        for (int i = 0; i < (int)s.size(); i++) {
            char ch = s[i];
            if (!seen[ch - 'a']) {
                while (!st.empty() && st.back() > ch && last_idx[st.back() - 'a'] > i) {
                    seen[st.back() - 'a'] = false;
                    st.pop_back();
                }
                st.push_back(ch);
                seen[ch - 'a'] = true;
            }
        }
        return st;
    }
};

class Solution {
    public String removeDuplicateLetters(String s) {
        int[] lastIdx = new int[26];
        for (int i = 0; i < s.length(); i++) lastIdx[s.charAt(i) - 'a'] = i;
        boolean[] seen = new boolean[26];
        char[] st = new char[26];
        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (!seen[ch - 'a']) {
                while (top > 0 && st[top - 1] > ch && lastIdx[st[top - 1] - 'a'] > i) {
                    seen[st[--top] - 'a'] = false;
                }
                st[top++] = ch;
                seen[ch - 'a'] = true;
            }
        }
        return new String(st, 0, top);
    }
}

var removeDuplicateLetters = function(s) {
    const lastIdx = {};
    for (let i = 0; i < s.length; i++) lastIdx[s[i]] = i;
    const st = [];
    const seen = new Set();
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (!seen.has(ch)) {
            while (st.length > 0 && st[st.length - 1] > ch && lastIdx[st[st.length - 1]] > i) {
                seen.delete(st.pop());
            }
            st.push(ch);
            seen.add(ch);
        }
    }
    return st.join('');
};
